from openai import OpenAI
client = OpenAI()

def llm(prompt):
    resp = client.chat.completions.create(model='deepseek-v4-pro', messages=[{'role':'user','content':prompt}])
    return resp.choices[0].message.content

# 子 Agent
def search_agent(query):
    return llm(f'搜索:{query},返回一句话结果')

def calc_agent(expr):
    return str(eval(expr))

# Supervisor, 根据任务类型选子 Agent
def supervisor(task):
    # 用 LLM 判断任务类型
    task_type = llm(f'判断任务类型(回复search或calc):{task}')
    if 'search' in task_type.lower():
        return search_agent(task)
    elif 'calc' in task_type.lower():
        return calc_agent(task)
    return '未知任务'

print(supervisor('搜索 AI 最新进展'))
print(supervisor('计算 123*456'))

